104	/** Minimal event shape for session history mapping. */
105	export type ISessionEvent =
106		| ISessionEventToolStart
107		| ISessionEventToolComplete
108		| ISessionEventMessage
109		| ISessionEventSubagentStarted
110		| ISessionEventSkillInvoked
111		| { type: string; data?: unknown };
