154	/**
155	 * Mutable per-turn state used while iterating events. The parent session
156	 * has one builder; each subagent turn (one per `parentToolCallId`) has its
157	 * own builder so inner events route there directly.
158	 */
159	interface ITurnBuilder {
160		id: string;
161		userMessage: UserMessage;
162		readonly responseParts: ResponsePart[];
163		/** Tool starts seen but not yet completed in this turn, keyed by toolCallId. */
164		readonly pendingTools: Map<string, IToolStartInfo>;
165	}
166	
167	function newTurnBuilder(id: string, text: string, attachments?: MessageAttachment[]): ITurnBuilder {
168		const userMessage: UserMessage = attachments?.length ? { text, attachments } : { text };
169		return { id, userMessage, responseParts: [], pendingTools: new Map() };
170	}
171	
172	function finalizeTurn(builder: ITurnBuilder, state: TurnState): Turn {
173		return {
174			id: builder.id,
175			userMessage: builder.userMessage,
176			responseParts: builder.responseParts,
177			usage: undefined,
178			state,
179		};
180	}
