 * When a matching `tool.execution_complete` payload is available (a completion
 * without a preceding start), its `success` and `error`/`result` drive the
 * part. With no completion at all the tool call is reported as a successful
 * invocation with no result content.
 */
function makeFallbackToolCallPart(
	req: { toolCallId: string; name: string; arguments?: unknown },
	completeData: ISessionEventToolComplete['data'] | undefined,
	workingDirectory: URI | undefined,
): ResponsePart {
	const rawArgs = req.arguments !== undefined ? tryStringify(req.arguments) : undefined;
	let parameters: Record<string, unknown> | undefined;
	if (rawArgs) {
		try { parameters = JSON.parse(rawArgs) as Record<string, unknown>; } catch { /* ignore */ }
	}
	const cleaned = stripRedundantCdPrefix(req.name, parameters, workingDirectory) ? tryStringify(parameters) : undefined;
	const toolArgs = cleaned ?? rawArgs;
	const toolKind = getToolKind(req.name);
	const displayName = getToolDisplayName(req.name);
	const success = completeData ? completeData.success : true;
	const toolOutput = completeData?.error?.message ?? completeData?.result?.content;
	const content: ToolResultContent[] | undefined = toolOutput !== undefined
		? [{ type: ToolResultContentType.Text, text: toolOutput }]
		: undefined;
	const tc: ToolCallCompletedState = {
		status: ToolCallStatus.Completed,
		toolCallId: req.toolCallId,
		toolName: req.name,
		displayName,
		invocationMessage: getInvocationMessage(req.name, displayName, parameters),
		toolInput: getToolInputString(req.name, parameters, toolArgs),
		success,
		pastTenseMessage: getPastTenseMessage(req.name, displayName, parameters, success),
		content,
		error: completeData?.error,
		confirmed: ToolCallConfirmationReason.NotNeeded,
		_meta: {
			toolKind,
			language: toolKind === 'terminal' ? getShellLanguage(req.name) : undefined,
		},
	};
	return { kind: ResponsePartKind.ToolCall, toolCall: tc };
}

